-- Part 2: hand-written.
ALTER TABLE calendar_connections
  ADD CONSTRAINT calendar_connections_provider_check CHECK (provider IN ('GOOGLE', 'MICROSOFT')),
  ADD CONSTRAINT calendar_connections_status_check CHECK (status IN ('ACTIVE', 'ERROR'));
ALTER TABLE calendar_oauth_states
  ADD CONSTRAINT calendar_oauth_states_provider_check CHECK (provider IN ('GOOGLE', 'MICROSOFT')),
  ADD CONSTRAINT calendar_oauth_states_hash_check CHECK (state_hash ~ '^[0-9a-f]{64}$'),
  ADD CONSTRAINT calendar_oauth_states_expiry_check CHECK (expires_at <= created_at + interval '10 minutes');
ALTER TABLE calendar_event_links
  ADD CONSTRAINT calendar_event_links_provider_check CHECK (provider IN ('GOOGLE', 'MICROSOFT')),
  ADD CONSTRAINT calendar_event_links_response_check CHECK (last_response IS NULL OR last_response IN ('ACCEPTED', 'DECLINED', 'NEEDS_ACTION'));
ALTER TABLE calendar_busy
  ADD CONSTRAINT calendar_busy_range_check CHECK (end_at > start_at);

DO $$
DECLARE
  t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['calendar_connections', 'calendar_oauth_states', 'calendar_event_links', 'calendar_busy'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY %I ON %I FOR ALL
         USING (org_id = NULLIF(current_setting(''app.org_id'', true), '''')::uuid)
         WITH CHECK (org_id = NULLIF(current_setting(''app.org_id'', true), '''')::uuid)',
      t || '_org_policy', t);
  END LOOP;
END
$$;
GRANT SELECT, INSERT, UPDATE, DELETE ON calendar_connections, calendar_oauth_states, calendar_event_links, calendar_busy TO hrvo_app;

-- The OAuth callback arrives without a session (a browser redirect from the provider).
CREATE FUNCTION fn_lookup_calendar_state(p_state_hash VARCHAR)
RETURNS TABLE (id UUID, org_id UUID, user_id UUID, provider VARCHAR, verifier VARCHAR, expires_at TIMESTAMPTZ)
SECURITY DEFINER
SET search_path = public
LANGUAGE plpgsql AS $$
BEGIN
  RETURN QUERY SELECT s.id, s.org_id, s.user_id, s.provider, s.verifier, s.expires_at FROM calendar_oauth_states s WHERE s.state_hash = p_state_hash;
END;
$$;
REVOKE ALL ON FUNCTION fn_lookup_calendar_state(VARCHAR) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fn_lookup_calendar_state(VARCHAR) TO hrvo_app;
